library(readr)
library(dplyr)
library(tidyr)
library(purrr)
library(haven)
library(labelled)

# Load all files
wave1 <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
wave4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t", show_col_types = FALSE)
ns8_main <- read_delim("data/input/ns8_2015_main_interview.tab", delim = "\t", show_col_types = FALSE)
ns8_derived <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t", show_col_types = FALSE)
ns9_main <- read_delim("data/input/ns9_2022_main_interview.tab", delim = "\t", show_col_types = FALSE)
ns9_derived <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t", show_col_types = FALSE)

# Merge all files by NSID
df <- full_join(wave1, wave4, by = "NSID")
df <- full_join(df, ns8_main, by = "NSID")
df <- full_join(df, ns8_derived, by = "NSID")
df <- full_join(df, ns9_main, by = "NSID")
df <- full_join(df, ns9_derived, by = "NSID")

# Map W8DHANVQH to collapsed 5-level NVQ scheme
map_w8dh <- function(x) {
  case_when(
    x %in% c(1, 2, 3) ~ 1L,
    x %in% c(4, 5) ~ 0L,
    x == 95 ~ 3L,
    x == 96 ~ 4L,
    x %in% c(-1, -8, -9) ~ x,
    TRUE ~ as.integer(x)
  )
}

# Map W8VCQU* to collapsed 5-level NVQ scheme
map_w8vc <- function(var, label) {
  case_when(
    var == 1 ~ case_when(
      label %in% c("Youth training certificate", "Key Skills", "Modern apprenticeship/trade apprenticeship", 
                   "RSA/OCR/Clerical and commercial qualifications", "City and Guilds Certificate",
                   "GNVQ/GSVQ", "NVQ/SVQ - Level 1 - 2", "NVQ/SVQ - Level 3 - 5",
                   "BTEC/BEC/TEC/EdExcel/LQL", "SCOTVEC, SCOTEC or SCOTBEC") ~ 1L,
      label %in% c("Basic skills", "Entry level qualifications (Wales)") ~ 2L,
      label %in% c("HNC/HND", "ONC/OND") ~ 0L,
      TRUE ~ 3L
    ),
    var == 0 ~ NA_integer_,
    var == -1 ~ -1L,
    var == -8 ~ -8L,
    var == -9 ~ -9L,
    TRUE ~ as.integer(var)
  )
}

# Derive educ25
df$w8dh_mapped <- map_w8dh(df$W8DHANVQH)

vcqu_vars <- paste0("W8VCQU0", c("A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L", "M", "N", "O", "P", "Q", "R"))
vcqu_labels <- c("Youth training certificate", "Key Skills", "Basic skills", 
                 "Entry level qualifications (Wales)", "Modern apprenticeship/trade apprenticeship",
                 "RSA/OCR/Clerical and commercial qualifications", "City and Guilds Certificate",
                 "GNVQ/GSVQ", "NVQ/SVQ - Level 1 - 2", "NVQ/SVQ - Level 3 - 5",
                 "HNC/HND", "ONC/OND", "BTEC/BEC/TEC/EdExcel/LQL", "SCOTVEC, SCOTEC or SCOTBEC",
                 "Other vocational, technical or professional", "None of the above",
                 "Don't know", "Refused")

for (i in seq_along(vcqu_vars)) {
