}

find_highest_qual <- function(row) {
  valid <- row[!is.na(row) & !row %in% c(-1, -8, -9)]
  if (length(valid) > 0) {
    return(min(valid))
  }
  missing <- row[row %in% c(-8, -9, -1)]
  missing <- missing[!is.na(missing)]
  if (length(missing) > 0) {
    if (any(missing == -9)) return(-9L)
    if (any(missing == -8)) return(-8L)
    return(min(missing))
  }
  return(NA_integer_)
}

all_mapped_cols <- c("w8dh_mapped", paste0("vcqu_", vcqu_vars))
df$educ25 <- apply(df[, all_mapped_cols], 1, find_highest_qual)

educ25_levels <- c("NVQ 4-5 equivalent", "NVQ 1-3 equivalent", "Entry level or no qualifications", 
                   "Other qualifications not mappable to the NVQ framework", "None of these qualifications",
                   "Refused", "Don't know", "Not applicable")
df$educ25 <- factor(df$educ25, levels = c(0, 1, 2, 3, 4, -9, -8, -1), 
                    labels = educ25_levels)

# Derive educ32
map_nvqh <- function(x) {
  case_when(
    x %in% c(1, 2, 3) ~ 1L,
    x %in% c(4, 5) ~ 0L,
    x == 0 ~ 2L,
    x == 95 ~ 3L,
    x == 96 ~ 4L,
    x %in% c(-1, -8, -9) ~ x,
