  acqu_values <- row[acqu_vars]

  if (!is.na(row["W9ACQU0T"]) && row["W9ACQU0T"] == 1) return(-8L)
  if (!is.na(row["W9ACQU0U"]) && row["W9ACQU0U"] == 1) return(-9L)
  if (!is.na(row["W9ACQU0V"]) && row["W9ACQU0V"] == 1) return(-2L)

  for (i in seq_along(acqu_vars)) {
    if (!is.na(acqu_values[i]) && acqu_values[i] == 1) {
      return(as.integer(i))
    }
  }

  if (all(acqu_values == -1, na.rm = TRUE)) return(-1L)
  if (all(acqu_values == -3, na.rm = TRUE)) return(-3L)

  return(19L)
}

