}

find_highest_qual <- function(row) {
  valid <- row[!is.na(row) & !row %in% c(-1, -8, -9)]
  if (length(valid) > 0) {
    return(min(valid))
  }
  missing <- row[row %in% c(-8, -9, -1)]
  missing <- missing[!is.na(missing)]
  if (length(missing) > 0) {
    if (any(missing == -9)) return(-9L)
    if (any(missing == -8)) return(-8L)
