find_highest_qual32 <- function(da, dv) {
  valid <- c()
  if (!is.na(da) && !da %in% c(-1, -8, -9)) valid <- c(valid, da)
  if (!is.na(dv) && !dv %in% c(-1, -8, -9)) valid <- c(valid, dv)
  if (length(valid) > 0) {
    return(min(valid))
  }
  missing <- c()
  if (!is.na(da) && da %in% c(-1, -8, -9)) missing <- c(missing, da)
  if (!is.na(dv) && dv %in% c(-1, -8, -9)) missing <- c(missing, dv)
  if (length(missing) > 0) {
    if (any(missing == -9)) return(-9L)
    if (any(missing == -8)) return(-8L)
    return(min(missing))
  }
  return(NA_integer_)
}

